<?php include "config.php"; if($_POST){ $name=$_POST['fullname']; $user=$_POST['username']; $pass=password_hash($_POST['password'],PASSWORD_DEFAULT); $role=$_POST['role']; $s=$conn->prepare("INSERT INTO users(fullname,username,password,role) VALUES(?,?,?,?)"); $s->bind_param('ssss',$name,$user,$pass,$role); $s->execute(); header('Location: users.php'); exit; } ?><!DOCTYPE html><html><head><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="container mt-4"><h2>Nuevo Usuario</h2><form method='post'><input class='form-control mb-2' name='fullname' placeholder='Nombre'><input class='form-control mb-2' name='username' placeholder='Usuario'><input class='form-control mb-2' type='password' name='password' placeholder='Password'><select class='form-control mb-2' name='role'><option value='admin'>Admin</option><option value='supervisor'>Supervisor</option><option value='viewer'>Viewer</option></select><button class='btn btn-primary'>Guardar</button></form></body></html>